import { useMemo, useState, type ComponentProps, type ElementType, type ReactNode } from 'react';
import {
  Activity, ArrowUpRight, BadgeAlert, Bell, Check, ChevronRight, CircleHelp,
  Clock3, CloudOff, Database, Download, FileSearch, Flame, Gauge, Info,
  History as HistoryIconComponent, LockKeyhole, MapPin, Pause, Play, RefreshCw, Search, Siren, StepForward,
  Thermometer, TimerReset, TriangleAlert, UserRound, WifiOff, X,
  Cable,
  type LucideIcon,
} from 'lucide-react';
import { mockActions, mockAlerts, mockAudit, mockHazards, mockIncidents, mockNodes, mockSOS, mockTelemetry, mockScenarios, mockServices, type Incident, type State } from '@/data/mock';
import { MapSurface } from '@/components/nexalert/MapSurface';

const stateClass: Record<State, string> = { NORMAL: 'state-normal', WATCH: 'state-watch', SUSPECTED: 'state-suspected', CONFIRMED: 'state-confirmed', CRITICAL: 'state-critical', RESOLVED: 'state-resolved' };

export function StateChip({ state }: { state: State | string }) {
  const label = state.replaceAll('_', ' ');
  const className = stateClass[state as State] || (state === 'GOOD' || state === 'OPERATIONAL' || state === 'ONLINE' ? 'state-normal' : state === 'DEGRADED' || state === 'REVIEW' || state === 'IN PROGRESS' ? 'state-watch' : state === 'UNAVAILABLE' || state === 'UNREACHABLE' || state === 'BLOCKED' ? 'state-critical' : 'state-resolved');
  return <span className={`state-chip ${className}`}><span aria-hidden className="h-1.5 w-1.5 rounded-full bg-current" />{label}</span>;
}

function Condition({ value }: { value: string }) {
  return <span className={`inline-flex items-center gap-1.5 font-mono text-[10px] ${value === 'GOOD' ? 'condition-good' : value === 'DEGRADED' ? 'condition-degraded' : 'condition-unknown'}`}><span className="h-1.5 w-1.5 rounded-sm border border-current" />{value}</span>;
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions?: ReactNode }) {
  return <div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow mb-1.5">{eyebrow}</div><h1 className="title-display m-0 text-[25px] text-slate-100">{title}</h1><p className="mb-0 mt-1.5 max-w-2xl text-[12px] leading-relaxed text-slate-500">{description}</p></div><div className="flex items-center gap-2">{actions}</div></div>;
}

function SectionTitle({ icon: Icon, children, meta }: { icon: ElementType; children: ReactNode; meta?: string }) {
  return <div className="mb-3 flex items-center gap-2"><Icon size={15} className="text-cyan-300" /><h2 className="m-0 text-[13px] font-bold text-slate-200">{children}</h2>{meta && <span className="ml-auto font-mono text-[10px] text-slate-600">{meta}</span>}</div>;
}

function Metric({ label, value, detail, tone = 'text-slate-100' }: { label: string; value: string; detail: string; tone?: string }) {
  return <div className="panel-flat p-3"><div className="eyebrow">{label}</div><div className={`mt-2 text-[21px] font-bold ${tone}`}>{value}</div><div className="mt-1 text-[10px] text-slate-500">{detail}</div></div>;
}

function ActionButton({ children, onClick, primary = false, testId }: { children: ReactNode; onClick?: () => void; primary?: boolean; testId: string }) {
  return <button type="button" onClick={onClick} className={`button-compact ${primary ? 'button-primary' : ''}`} data-testid={testId}>{children}</button>;
}

function Feedback({ message, onClose }: { message: string; onClose: () => void }) {
  return <div className="fixed bottom-4 right-4 z-50 flex max-w-xs items-center gap-3 rounded-md border border-cyan-300/30 bg-[#102731] px-3 py-2.5 text-[11px] text-cyan-100 shadow-2xl" role="status"><Check size={14} className="text-cyan-300" />{message}<button type="button" className="ml-auto text-slate-500 hover:text-white" onClick={onClose} data-testid="button-close-feedback"><X size={13} /></button></div>;
}

