export function AlertsPage() {
  const [alerts, setAlerts] = useState(mockAlerts);
  const [feedback, setFeedback] = useState('');
  const advance = (id: string) => { setAlerts((current) => current.map((alert) => alert.id === id ? { ...alert, state: alert.state === 'REVIEW' ? 'AUTHORIZED' : alert.state === 'AUTHORIZED' ? 'ISSUED' : alert.state, lastChange: '08:42 UTC' } : alert)); setFeedback('Lifecycle state updated in local demo view'); };
  const lifecycle = ['DRAFT', 'REVIEW', 'AUTHORIZED', 'ISSUED', 'DELIVERING', 'DELIVERED', 'OPENED', 'ACKNOWLEDGED', 'UNREACHABLE', 'STAND DOWN'];
  return <div className="content-area"><PageHeader eyebrow="Coordination / canonical emergency events" title="Alert management" description="Track approval, issuance, delivery, and acknowledgement without implying that a recommendation has already been sent." actions={<ActionButton primary testId="button-draft-alert" onClick={() => setFeedback('New alert draft opened locally')}><Bell size={13} />Draft alert</ActionButton>} /><div className="mb-4 panel p-4"><SectionTitle icon={Bell} meta="online and offline remain distinct">Alert lifecycle</SectionTitle><div className="flex gap-1 overflow-x-auto pb-1">{lifecycle.map((stage, index) => <div key={stage} className={`flex min-w-max items-center gap-2 rounded-md border px-2.5 py-2 text-[9px] font-mono ${index < 4 ? 'border-cyan-300/20 bg-cyan-300/[.04] text-cyan-100' : 'border-slate-800 text-slate-600'}`}><span>{String(index + 1).padStart(2, '0')}</span>{stage}</div>)}</div></div><div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_340px]"><div className="panel overflow-hidden"><div className="divide-y divide-slate-800/70">{alerts.map((alert) => <div key={alert.id} className="flex flex-wrap items-center gap-3 p-4"><div className="min-w-[220px] flex-1"><div className="text-[12px] font-bold text-slate-200">{alert.title}</div><div className="mt-1 text-[10px] text-slate-500">{alert.id} · {alert.audience} · owner {alert.owner}</div></div><div className="text-right"><StateChip state={alert.state} /><div className="mt-1 text-[9px] text-slate-600">{alert.channel}</div></div><button type="button" className="button-compact" onClick={() => advance(alert.id)} data-testid={`button-advance-alert-${alert.id}`}>Advance <ArrowUpRight size={12} /></button></div>)}</div></div><div className="space-y-4"><div className="panel p-4"><div className="eyebrow">Delivery by channel</div><div className="mt-3 space-y-3 text-[11px]"><div className="flex justify-between"><span className="text-slate-500">Online web</span><span className="text-cyan-200">1,108 delivered · 17 open</span></div><div className="flex justify-between"><span className="text-slate-500">Local portal</span><span className="text-amber-200">68 cached · local mode</span></div><div className="flex justify-between"><span className="text-slate-500">SMS / voice</span><span className="text-slate-400">Integration unavailable</span></div></div></div><div className="rounded-md border border-amber-300/15 bg-amber-300/[.04] p-3 text-[10px] leading-relaxed text-amber-100/75"><LockKeyhole size={14} className="mb-2 text-amber-200" />Issuance requires authorized human approval. The UI never claims a message was delivered without a confirmed lifecycle state.</div></div></div>{feedback && <Feedback message={feedback} onClose={() => setFeedback('')} />}</div>;
}

