export function SystemPage() {
  const [showConfig, setShowConfig] = useState(false);
  return <div className="content-area"><PageHeader eyebrow="System / service health" title="System" description="Make connection, local fallback, feature state, and freshness visible instead of treating empty panels as zero activity." actions={<ActionButton testId="button-toggle-config" onClick={() => setShowConfig((value) => !value)}><SettingsIcon size={13} />{showConfig ? 'Hide configuration' : 'View configuration'}</ActionButton>} /><div className="mb-4 grid grid-cols-2 gap-2 lg:grid-cols-4"><Metric label="Master" value="AVAILABLE" detail="Local authority master" tone="text-emerald-200" /><Metric label="Internet" value="UNAVAILABLE" detail="Local mode active" tone="text-amber-200" /><Metric label="Last sync" value="18 min ago" detail="Cloud sync is stale" tone="text-amber-200" /><Metric label="Data condition" value="DEGRADED" detail="East camera delayed" tone="text-amber-200" /></div><div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_340px]"><div className="panel overflow-hidden"><div className="border-b border-slate-800 p-3"><SectionTitle icon={Activity} meta={`${mockServices.length} services`}>Service health</SectionTitle></div><div className="divide-y divide-slate-800/70">{mockServices.map((service) => <div key={service.id} className="flex flex-wrap items-center gap-3 p-4"><div className="min-w-[220px] flex-1"><div className="text-[12px] font-bold text-slate-200">{service.name}</div><div className="mt-1 text-[10px] text-slate-500">{service.detail} · dependency {service.dependency}</div></div><div className="text-right"><StateChip state={service.state} /><div className="mt-1 text-[9px] text-slate-600">{service.lastCheck}</div></div></div>)}</div></div><div className="space-y-4"><div className="panel p-4"><SectionTitle icon={CloudOff} meta="explicit fallback">Connectivity interpretation</SectionTitle><div className="space-y-3 text-[11px]"><div className="flex gap-2"><span className="mt-1 h-2 w-2 rounded-full bg-emerald-300" /><div><b className="text-slate-200">Master available</b><div className="mt-0.5 text-slate-500">Local authority functions remain available.</div></div></div><div className="flex gap-2"><span className="mt-1 h-2 w-2 rounded-full bg-amber-300" /><div><b className="text-slate-200">Internet unavailable</b><div className="mt-0.5 text-slate-500">Cloud-backed sync and external delivery are affected.</div></div></div></div></div>{showConfig && <div className="panel p-4"><div className="eyebrow">Configuration visibility</div><div className="mt-3 space-y-2 font-mono text-[10px] text-slate-500"><div className="flex justify-between"><span>projection.version</span><span className="text-slate-200">fire-v2.4.1</span></div><div className="flex justify-between"><span>node.stale_threshold</span><span className="text-slate-200">120 sec</span></div><div className="flex justify-between"><span>offline.portal</span><span className="text-emerald-200">enabled</span></div></div></div>}</div></div></div>;
}

function SettingsIcon(props: ComponentProps<typeof Activity>) { return <LockKeyhole {...props} />; }

function TableShell({ children }: { children: ReactNode }) {
  return <div className="panel overflow-hidden"><div className="overflow-x-auto">{children}</div></div>;
}

function TelemetryPageLegacy() {
  const [query, setQuery] = useState('');
  const records = mockTelemetry.filter((record) => `${record.source} ${record.signal} ${record.observed}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="content-area"><PageHeader eyebrow="Field intelligence / inspection" title="Telemetry" description="Trace raw observations into operator-readable state. No value here is presented as an autonomous conclusion." actions={<label className="flex items-center gap-2 rounded-md border border-slate-800 bg-slate-900/70 px-2.5 py-2 text-slate-500"><Search size={13} /><input value={query} onChange={(event) => setQuery(event.target.value)} aria-label="Filter telemetry" data-testid="input-filter-telemetry" placeholder="Filter telemetry" className="w-32 bg-transparent text-[11px] text-slate-200 outline-none" /></label>} /><div className="mb-4 grid grid-cols-2 gap-2 lg:grid-cols-4"><Metric label="Records / frame" value="4" detail="Accepted observations" /><Metric label="Good quality" value="2" detail="Within freshness window" tone="text-emerald-200" /><Metric label="Degraded" value="1" detail="Delayed camera path" tone="text-amber-200" /><Metric label="Unknown" value="1" detail="Node unreachable" tone="text-slate-300" /></div><TableShell><table className="w-full min-w-[720px] text-left text-[11px]"><thead className="bg-slate-900/60 text-[9px] uppercase tracking-wider text-slate-600"><tr><th className="px-4 py-3">Source</th><th className="px-4 py-3">Signal</th><th className="px-4 py-3">Observed</th><th className="px-4 py-3">Derived state</th><th className="px-4 py-3">Received</th><th className="px-4 py-3">Quality</th></tr></thead><tbody className="divide-y divide-slate-800/70">{records.map((record) => <tr key={record.id} className="hover:bg-slate-800/30" data-testid={`row-telemetry-${record.id}`}><td className="px-4 py-3 font-semibold text-slate-200">{record.source}</td><td className="px-4 py-3 font-mono text-slate-400">{record.signal}</td><td className="px-4 py-3 text-cyan-100">{record.observed}</td><td className="px-4 py-3"><StateChip state={record.state.toUpperCase()} /></td><td className="px-4 py-3 text-slate-500">{record.receivedAt}</td><td className="px-4 py-3"><Condition value={record.quality} /></td></tr>)}</tbody></table></TableShell><div className="mt-4 rounded-md border border-amber-300/15 bg-amber-300/[.03] p-3 text-[10px] leading-relaxed text-amber-100/70"><Info size={13} className="mr-2 inline text-amber-300" />Raw telemetry is retained as evidence. A derived state can be stale, degraded, or unknown and must be reviewed in context.</div></div>;
}

function CitizenSOSPageLegacy() {
  const [filter, setFilter] = useState('All');
  const [feedback, setFeedback] = useState('');
  const [items, setItems] = useState(mockSOS);
  const filtered = items.filter((item) => filter === 'All' || item.state === filter);
  const advance = (id: string) => { setItems((current) => current.map((item) => item.id === id ? { ...item, state: item.state === 'NEW' ? 'TRIAGED' : item.state === 'TRIAGED' ? 'ASSIGNED' : item.state === 'ASSIGNED' ? 'RESOLVED' : 'RESOLVED' } : item)); setFeedback(`Local status updated for ${id}`); };
  return <div className="content-area"><PageHeader eyebrow="Public requests / triage" title="Citizen SOS" description="Handle inbound requests with explicit triage state, location, channel, and honest uncertainty." actions={<ActionButton testId="button-refresh-sos" onClick={() => setFeedback('SOS queue refreshed from local mock data')}><RefreshCw size={13} />Refresh queue</ActionButton>} /><div className="mb-4 flex flex-wrap gap-1 rounded-md border border-slate-800 bg-slate-900/40 p-1">{['All', 'NEW', 'TRIAGED', 'ASSIGNED', 'RESOLVED'].map((item) => <button type="button" key={item} onClick={() => setFilter(item)} className={`rounded px-3 py-2 text-[10px] font-semibold ${filter === item ? 'bg-cyan-300/10 text-cyan-200' : 'text-slate-500'}`} data-testid={`button-sos-filter-${item.toLowerCase()}`}>{item}</button>)}</div><div className="grid gap-3">{filtered.map((item) => <div className="panel p-4" key={item.id} data-testid={`card-sos-${item.id}`}><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex items-start gap-3"><div className="grid h-8 w-8 place-items-center rounded-md border border-red-300/20 bg-red-300/[.08] text-red-300"><Siren size={15} /></div><div><div className="text-[13px] font-bold text-slate-100">{item.id} · {item.caller}</div><div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-[10px] text-slate-500"><span className="flex items-center gap-1"><MapPin size={11} />{item.location}</span><span>{item.channel}</span><span>{item.receivedAt}</span></div></div></div><StateChip state={item.state} /></div><p className="mb-0 mt-3 rounded-md bg-slate-900/50 p-3 text-[11px] leading-relaxed text-slate-400">{item.note}</p><div className="mt-3 flex flex-wrap items-center justify-between gap-2"><span className="text-[10px] text-slate-600">Location requires operator confirmation before dispatch.</span>{item.state !== 'RESOLVED' && <ActionButton primary testId={`button-advance-sos-${item.id}`} onClick={() => advance(item.id)}>{item.state === 'NEW' ? 'Triage request' : item.state === 'TRIAGED' ? 'Assign request' : 'Resolve request'} <ArrowUpRight size={13} /></ActionButton>}</div></div>)}</div>{feedback && <Feedback message={feedback} onClose={() => setFeedback('')} />}</div>;
}

function AlertsPageLegacy() {
  const [alerts, setAlerts] = useState(mockAlerts);
  const [feedback, setFeedback] = useState('');
  const advance = (id: string) => setAlerts((current) => current.map((item) => item.id === id ? { ...item, state: item.state === 'DRAFT' ? 'REVIEW' : item.state === 'REVIEW' ? 'AUTHORIZED' : item.state === 'AUTHORIZED' ? 'ISSUED' : item.state } : item));
  return <div className="content-area"><PageHeader eyebrow="Public messaging / lifecycle" title="Alerts" description="Draft, review, authorize, and issue public alerts with clear ownership. Issuing is never automatic." actions={<ActionButton primary testId="button-draft-alert" onClick={() => setFeedback('New alert draft created locally')}>+ Draft alert</ActionButton>} /><div className="mb-4 rounded-md border border-amber-300/15 bg-amber-300/[.04] p-3 text-[10px] text-amber-100/75"><LockKeyhole size={13} className="mr-2 inline text-amber-300" />Public issue requires an authorized human. This first pass updates only local mock state.</div><div className="grid gap-3">{alerts.map((alert) => <div className="panel p-4" key={alert.id} data-testid={`card-alert-${alert.id}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><span className="font-mono text-[10px] text-slate-600">{alert.id}</span><StateChip state={alert.state} /></div><h2 className="mt-2 text-[14px] font-bold text-slate-100">{alert.title}</h2><div className="mt-1 text-[10px] text-slate-500">Audience: {alert.audience} · Channel: {alert.channel}</div></div><div className="text-right text-[10px] text-slate-600"><div>{alert.owner}</div><div className="mt-1">{alert.lastChange}</div></div></div><div className="mt-4 flex flex-wrap gap-2">{alert.state === 'REVIEW' && <ActionButton primary testId={`button-authorize-alert-${alert.id}`} onClick={() => { advance(alert.id); setFeedback(`${alert.id} marked authorized locally`); }}><Check size={13} />Authorize for issue</ActionButton>}{alert.state === 'AUTHORIZED' && <ActionButton primary testId={`button-issue-alert-${alert.id}`} onClick={() => { advance(alert.id); setFeedback(`${alert.id} issued locally; no external message sent`); }}><Bell size={13} />Issue alert</ActionButton>}<ActionButton testId={`button-open-alert-${alert.id}`} onClick={() => setFeedback(`Opened lifecycle review for ${alert.id}`)}><FileSearch size={13} />Open review</ActionButton></div></div>)}</div>{feedback && <Feedback message={feedback} onClose={() => setFeedback('')} />}</div>;
}

function HistoricalPageLegacy() {
  const [range, setRange] = useState('24 hours');
  return <div className="content-area"><PageHeader eyebrow="Analysis / retained picture" title="Historical" description="Compare prior operational frames and response records without rewriting what was known at the time." actions={<select value={range} onChange={(event) => setRange(event.target.value)} className="rounded-md border border-slate-800 bg-slate-900 px-3 py-2 text-[11px] text-slate-300 outline-none" data-testid="select-history-range"><option>24 hours</option><option>7 days</option><option>30 days</option></select>} /><div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_330px]"><div className="space-y-4"><div className="panel p-4"><SectionTitle icon={HistoryIcon} meta={range}>Operational frames</SectionTitle><div className="relative mt-6 h-48 border-b border-l border-slate-700/80"><div className="absolute inset-x-4 bottom-0 top-4 flex items-end justify-between gap-2">{[36, 48, 42, 64, 58, 82, 71, 92, 76, 88, 68, 84].map((height, index) => <div key={index} className="group flex h-full flex-1 items-end"><div className={`w-full rounded-t-sm ${index > 7 ? 'bg-red-300/45' : index > 4 ? 'bg-amber-300/45' : 'bg-cyan-300/35'}`} style={{ height: `${height}%` }} title={`frame ${index + 1}`} /></div>)}</div><div className="absolute -left-10 top-1 font-mono text-[9px] text-slate-600">HIGH</div><div className="absolute -left-10 bottom-1 font-mono text-[9px] text-slate-600">LOW</div></div><div className="mt-3 flex justify-between text-[9px] text-slate-600"><span>08:00</span><span>12:00</span><span>16:00</span><span>20:00</span><span>NOW</span></div></div><TableShell><table className="w-full min-w-[640px] text-left text-[11px]"><thead className="bg-slate-900/60 text-[9px] uppercase tracking-wider text-slate-600"><tr><th className="px-4 py-3">Frame</th><th className="px-4 py-3">Context</th><th className="px-4 py-3">Known state</th><th className="px-4 py-3">Recorded</th></tr></thead><tbody className="divide-y divide-slate-800/70">{['08:42 UTC', '08:30 UTC', '08:00 UTC', '07:30 UTC'].map((time, index) => <tr key={time} className="hover:bg-slate-800/30"><td className="px-4 py-3 font-mono text-cyan-200">{time}</td><td className="px-4 py-3 text-slate-300">{['Juniper Ridge perimeter update', 'Black Creek gauge rise', 'South utility anomaly', 'North basin cooling trend'][index]}</td><td className="px-4 py-3"><StateChip state={['CONFIRMED', 'WATCH', 'SUSPECTED', 'RESOLVED'][index]} /></td><td className="px-4 py-3 text-slate-500">Audit record retained</td></tr>)}</tbody></table></TableShell></div><div className="space-y-4"><div className="panel p-4"><SectionTitle icon={Clock3} meta="retained">Review notes</SectionTitle><div className="space-y-3 text-[10px] leading-relaxed text-slate-500"><p className="m-0">Historical frames preserve the information condition and freshness known at capture time.</p><p className="m-0">A later outcome does not change what was available to an operator earlier.</p></div></div><div className="panel p-4"><div className="eyebrow">Saved comparison</div><div className="mt-2 text-[12px] font-semibold text-slate-200">Juniper Ridge growth review</div><div className="mt-1 text-[10px] text-slate-500">08:00 → 08:42 UTC · 4 frames</div><ActionButton testId="button-open-comparison" onClick={() => {}}>Open comparison <ChevronRight size={13} /></ActionButton></div></div></div></div>;
}

function HistoryIcon(props: ComponentProps<typeof Activity>) { return <HistoryIconComponent {...props} />; }

function ResponsePageLegacy() {
  const [actions, setActions] = useState(mockActions);
  const [feedback, setFeedback] = useState('');
  const progress = (id: string) => setActions((current) => current.map((item) => item.id === id ? { ...item, state: item.state === 'PROPOSED' ? 'AUTHORIZED' : item.state === 'AUTHORIZED' ? 'IN PROGRESS' : item.state === 'IN PROGRESS' ? 'COMPLETE' : item.state } : item));
  return <div className="content-area"><PageHeader eyebrow="Coordination / human action" title="Response" description="Track recommendations, authorization, and execution separately. This surface never implies autonomous dispatch." actions={<ActionButton primary testId="button-new-response-action" onClick={() => setFeedback('New response action drafted locally')}>+ New action</ActionButton>} /><div className="grid gap-3">{actions.map((action) => <div key={action.id} className="panel p-4" data-testid={`card-response-${action.id}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><span className="font-mono text-[10px] text-slate-600">{action.id}</span><StateChip state={action.state} /></div><h2 className="mt-2 text-[14px] font-bold text-slate-100">{action.title}</h2><p className="mb-0 mt-1 text-[10px] text-slate-500">{action.note}</p></div><div className="text-right text-[10px] text-slate-500"><div>{action.owner}</div><div className="mt-1 text-amber-200">Due {action.due}</div></div></div><div className="mt-3 flex items-center justify-between gap-3"><div className="h-1.5 flex-1 overflow-hidden rounded-full bg-slate-800"><div className={`h-full rounded-full ${action.state === 'BLOCKED' ? 'bg-red-300/50' : action.state === 'COMPLETE' ? 'bg-emerald-300/60' : 'bg-cyan-300/60'}`} style={{ width: action.state === 'PROPOSED' ? '20%' : action.state === 'AUTHORIZED' ? '48%' : action.state === 'IN PROGRESS' ? '72%' : action.state === 'COMPLETE' ? '100%' : '12%' }} /></div>{!['COMPLETE', 'BLOCKED'].includes(action.state) && <ActionButton testId={`button-progress-action-${action.id}`} onClick={() => { progress(action.id); setFeedback(`${action.id} updated locally`); }}>{action.state === 'PROPOSED' ? 'Authorize' : action.state === 'AUTHORIZED' ? 'Start' : 'Complete'} <ArrowUpRight size={13} /></ActionButton>}{action.state === 'BLOCKED' && <span className="text-[10px] text-red-200">Manual verification required</span>}</div></div>)}</div>{feedback && <Feedback message={feedback} onClose={() => setFeedback('')} />}</div>;
}

function AuditPageLegacy() {
  const [query, setQuery] = useState('');
  const events = mockAudit.filter((event) => `${event.actor} ${event.action} ${event.scope}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="content-area"><PageHeader eyebrow="Governance / immutable record" title="Audit trail" description="A retained record of operator and system activity. Entries are not editable from this console." actions={<ActionButton testId="button-export-audit"><Download size={13} />Export record</ActionButton>} /><div className="mb-4 flex items-center justify-between gap-3 rounded-md border border-slate-800 bg-slate-900/40 p-3"><div className="flex items-center gap-2 text-[10px] text-slate-400"><LockKeyhole size={14} className="text-cyan-300" />Append-only local demo record · integrity check <span className="font-mono text-emerald-300">PASS</span></div><label className="hidden items-center gap-2 rounded border border-slate-800 bg-slate-950/50 px-2 py-1.5 text-slate-500 sm:flex"><Search size={12} /><input value={query} onChange={(event) => setQuery(event.target.value)} aria-label="Search audit trail" data-testid="input-search-audit" placeholder="Search trail" className="w-28 bg-transparent text-[10px] text-slate-200 outline-none" /></label></div><TableShell><table className="w-full min-w-[760px] text-left text-[11px]"><thead className="bg-slate-900/60 text-[9px] uppercase tracking-wider text-slate-600"><tr><th className="px-4 py-3">Timestamp</th><th className="px-4 py-3">Actor</th><th className="px-4 py-3">Action</th><th className="px-4 py-3">Scope</th><th className="px-4 py-3">Result</th></tr></thead><tbody className="divide-y divide-slate-800/70">{events.map((event) => <tr key={event.id} data-testid={`row-audit-${event.id}`} className="hover:bg-slate-800/30"><td className="px-4 py-3 font-mono text-slate-500">{event.timestamp}</td><td className="px-4 py-3 text-slate-300">{event.actor}</td><td className="px-4 py-3 font-semibold text-slate-200">{event.action}</td><td className="px-4 py-3 font-mono text-cyan-200">{event.scope}</td><td className="px-4 py-3"><span className={event.result === 'Recorded' ? 'text-emerald-300' : 'text-amber-200'}>{event.result}</span></td></tr>)}</tbody></table></TableShell></div>;
}

function SystemPageLegacy() {
  const [services, setServices] = useState(mockServices);
  const [feedback, setFeedback] = useState('');
  const toggle = (id: string) => setServices((current) => current.map((service) => service.id === id ? { ...service, state: service.state === 'DEGRADED' ? 'OPERATIONAL' : service.state } : service));
  return <div className="content-area"><PageHeader eyebrow="System / resilience" title="System" description="Understand what is available, what is degraded, and where the console is operating locally." actions={<ActionButton testId="button-run-health-check" onClick={() => setFeedback('Local health check completed at 08:42:16 UTC')}><Activity size={13} />Run local health check</ActionButton>} /><div className="mb-4 grid grid-cols-2 gap-2 lg:grid-cols-4"><Metric label="Master" value="Available" detail="Local authority master" tone="text-emerald-200" /><Metric label="Internet" value="Unavailable" detail="Local mode active" tone="text-amber-200" /><Metric label="Node ingest" value="Degraded" detail="East camera delayed" tone="text-amber-200" /><Metric label="Last audit" value="08:42:16" detail="Record integrity pass" /></div><div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_330px]"><div className="panel overflow-hidden"><div className="border-b border-slate-800 p-4"><SectionTitle icon={Activity} meta="4 services">Service health</SectionTitle></div><div className="divide-y divide-slate-800/70">{services.map((service) => <div key={service.id} className="flex flex-wrap items-center gap-3 p-4" data-testid={`row-service-${service.id}`}><div className="grid h-8 w-8 place-items-center rounded-md border border-slate-700 bg-slate-900/60">{service.state === 'UNAVAILABLE' ? <CloudOff size={15} className="text-red-300" /> : service.state === 'DEGRADED' ? <TriangleAlert size={15} className="text-amber-300" /> : <Check size={15} className="text-emerald-300" />}</div><div className="min-w-[180px] flex-1"><div className="text-[12px] font-semibold text-slate-200">{service.name}</div><div className="mt-1 text-[10px] text-slate-500">{service.detail} · dependency: {service.dependency}</div></div><div className="text-right"><StateChip state={service.state} /><div className="mt-1 text-[9px] text-slate-600">{service.lastCheck}</div></div>{service.state === 'DEGRADED' && <ActionButton testId={`button-recheck-${service.id}`} onClick={() => { toggle(service.id); setFeedback(`${service.name} recheck recorded locally`); }}>Recheck</ActionButton>}</div>)}</div></div><div className="space-y-4"><div className="panel p-4"><SectionTitle icon={Settings2Icon}>Configuration</SectionTitle><div className="space-y-3 text-[10px]"><div className="flex justify-between"><span className="text-slate-500">Operating mode</span><span className="font-mono text-cyan-200">LOCAL</span></div><div className="flex justify-between"><span className="text-slate-500">Authority region</span><span className="text-slate-200">North County</span></div><div className="flex justify-between"><span className="text-slate-500">Data retention</span><span className="text-slate-200">30 days</span></div></div></div><div className="rounded-md border border-red-300/15 bg-red-300/[.04] p-3 text-[10px] leading-relaxed text-red-100/70"><WifiOff size={14} className="mb-2 text-red-300" />Internet unavailable. External publication, remote node commands, and remote synchronization are unavailable in local mode.</div></div></div>{feedback && <Feedback message={feedback} onClose={() => setFeedback('')} />}</div>;
}

function Settings2Icon(props: ComponentProps<typeof Activity>) { return <Gauge {...props} />; }